static p224GeneratorTable: Lazy<Vec<p224Table>> = Lazy::new(|| {
    let mut tables: Vec<p224Table> = Vec::with_capacity(p224ElementLength * 2);
    let mut base = NewP224Point();
    base.SetGenerator();
    let mut i: usize = 0;
    while i < p224ElementLength * 2 {
        let mut tbl = p224Table([NewP224Point(); 15]);
        tbl.0[0].Set(base);
        let mut j: usize = 1;
        while j < 15 {
            let prev = tbl.0[j - 1];
            tbl.0[j].Add(prev, base);
            j += 1;
        }
        tables.push(tbl);
        let b = base;
        base.Double(b);
        let b = base;
        base.Double(b);
        let b = base;
        base.Double(b);
        let b = base;
        base.Double(b);
        i += 1;
    }
    return tables;
});

// go: sdk 1.25.5 crypto/internal/fips140/nistec/p224.go:442-453 p224Sqrt
/// Set e to a square root of x. If x is not a square, p224Sqrt returns
/// false and e is unchanged. e and x can overlap.
fn p224Sqrt(e: &mut P224Element, x: P224Element) -> bool {
    let mut candidate = P224Element::New();
    p224SqrtCandidate(&mut candidate, x);
    let mut square = P224Element::New();
    square.Square(candidate);
    if square.Equal(x) != 1 {
        return false;
    }
    e.Set(candidate);
    return true;
}

